import json,subprocess,sys,random
sys.path.insert(0,'/work/s'); import model; model.MAXLEN=15
def check(rows,label):
    stim=[{'rst':r[0],'rx':r[1]} for r in rows]
    json.dump(stim,open('/tmp/stim.json','w'))
    out=subprocess.run(['python3','/work/tools/run_candidate.py','/work/answer.v','/tmp/stim.json'],capture_output=True,text=True).stdout.strip().splitlines()
    exp=model.run(rows)
    if label=='first': print(out[:3])
    nums=[[int(v) for v in __import__('re').findall(r'=\s*(\w+)',l)] for l in out]
    seen=False;bad=0
    for i,(r,e,g) in enumerate(zip(rows,exp,nums)):
        if r[0]: seen=True
        if seen and e!=g[-4:] and e!=g[:4]:
            bad+=1
            if bad<5: print(label,i,e,out[i])
    print(label,'mismatches',bad,len(out),len(rows))
R=json.load(open('/work/trace.json'))['rows']
check([r[:2] for r in R],'first')
